-- Migration 0018: Task Dependencies (prerequisite DAG)
-- Many-to-many predecessor → successor edges between schedule_tasks.
-- Generated by the deterministic rule engine on blueprint import; also user-editable.
-- The legacy single-FK schedule_tasks.predecessor_task_id is backfilled with the
-- "primary" (most immediate) predecessor for the existing Gantt; this table is the
-- full graph used by the Project Overview DAG and any future critical-path logic.
-- Locked decisions: A-03 (RLS), T-42/T-50 (withTenantContext), T-48 (SET LOCAL)

CREATE TABLE task_dependencies (
  id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id            UUID NOT NULL REFERENCES tenants(id),
  project_id           UUID NOT NULL REFERENCES projects(id),
  predecessor_task_id  UUID NOT NULL REFERENCES schedule_tasks(id),
  successor_task_id    UUID NOT NULL REFERENCES schedule_tasks(id),
  dependency_type      TEXT NOT NULL DEFAULT 'finish_to_start'
    CHECK (dependency_type IN ('finish_to_start','start_to_start','finish_to_finish','start_to_finish')),
  origin               TEXT NOT NULL DEFAULT 'rule_engine'
    CHECK (origin IN ('rule_engine','manual')),
  created_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  deleted_at           TIMESTAMPTZ,
  created_by           UUID REFERENCES users(id),
  CONSTRAINT no_self_dependency CHECK (predecessor_task_id <> successor_task_id)
);

-- One live edge per (tenant, predecessor, successor); soft-deleted rows don't block re-create
CREATE UNIQUE INDEX idx_task_dependencies_unique
  ON task_dependencies(tenant_id, predecessor_task_id, successor_task_id)
  WHERE deleted_at IS NULL;
CREATE INDEX idx_task_dependencies_tenant         ON task_dependencies(tenant_id);
CREATE INDEX idx_task_dependencies_tenant_deleted ON task_dependencies(tenant_id, deleted_at);
CREATE INDEX idx_task_dependencies_project        ON task_dependencies(tenant_id, project_id);
CREATE INDEX idx_task_dependencies_predecessor    ON task_dependencies(tenant_id, predecessor_task_id);
CREATE INDEX idx_task_dependencies_successor      ON task_dependencies(tenant_id, successor_task_id);

ALTER TABLE task_dependencies ENABLE ROW LEVEL SECURITY;
ALTER TABLE task_dependencies FORCE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON task_dependencies
  USING (tenant_id = current_setting('app.current_tenant_id', TRUE)::UUID);
